'use strict';
(() => {
  const $ = (s, r=document) => r.querySelector(s);
  const $$ = (s, r=document) => [...r.querySelectorAll(s)];
  const app = $('#app');
  const modal = $('#modal');
  const modalContent = $('#modal-content');
  const toastRegion = $('#toast-region');
  const moneyFmt = new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});
  const numberFmt = new Intl.NumberFormat('pt-BR',{maximumFractionDigits:3});
  const state = {page:'dashboard',user:null,csrf:'',products:[],categories:[],discounts:[],stock:null,sales:[],expenses:[],suppliers:[],customers:[],purchases:[],users:[],cart:[],query:'',dateFrom:firstDay(),dateTo:today(),dashboard:null,analytics:null};
  let productSearchTimer=null, productSearchSeq=0, posSearchTimer=null, posSearchSeq=0;
  const pageNames = {dashboard:'Visão geral',products:'Produtos',categories:'Categorias',discounts:'Promoções e descontos',stock:'Controle de estoque',pos:'Frente de caixa',sales:'Vendas realizadas',finance:'Painel financeiro',purchases:'Compras e fornecedores',customers:'Clientes',settings:'Administração'};
  const icons = {dashboard:'◈',products:'▦',categories:'◫',discounts:'％',stock:'▤',pos:'▣',sales:'↗',finance:'◒',purchases:'⇄',customers:'♙',settings:'⚙'};
  function today(){return new Date().toLocaleDateString('en-CA');}
  function firstDay(){const d=new Date();d.setDate(1);return d.toLocaleDateString('en-CA');}
  function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function brl(v){return moneyFmt.format(Number(v||0));}
  function qty(v){return numberFmt.format(Number(v||0));}
  function dateShort(v){if(!v)return 'Não informado';const m=String(v).match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return `${m[3]}/${m[2]}/${m[1]}`;const d=new Date(v);return Number.isNaN(d.getTime())?esc(v):d.toLocaleDateString('pt-BR');}
  function dateTime(v){if(!v)return 'Não informado';const d=new Date(v);return Number.isNaN(d.getTime())?esc(v):d.toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit'});}
  function slugText(v){return String(v||'').split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase()||'MP';}
  function toast(message,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;toastRegion.append(el);window.setTimeout(()=>el.remove(),4500);}
  async function api(path,opts={}){
    const headers={'Accept':'application/json',...(opts.headers||{})};
    if(opts.body!==undefined){headers['Content-Type']='application/json';opts.body=JSON.stringify(opts.body);}
    if(state.csrf && !['GET','HEAD'].includes((opts.method||'GET').toUpperCase()))headers['X-CSRF-Token']=state.csrf;
    let res;
    try{res=await fetch(path,{credentials:'same-origin',...opts,headers});}
    catch(e){toast('Falha de conexão com o servidor local. Confira se o terminal continua aberto.','error');throw e;}
    const body=await res.json().catch(()=>({ok:false,error:'Resposta inválida do servidor.'}));
    if(!res.ok||!body.ok){if(res.status===401&&state.user){state.user=null;state.csrf='';renderAuth(false);}const msg=body.error||`Erro ${res.status}`;toast(msg,'error');throw new Error(msg);}
    return body.data;
  }
  async function boot(){
    try{const data=await api('/api/bootstrap');if(data.authenticated){state.user=data.user;state.csrf=data.user.csrf_token;await loadPage(state.page);renderApp();}else renderAuth(data.setup_required);}
    catch(e){app.innerHTML=`<div class="auth-wrap"><section class="auth-card"><div class="auth-logo"><div class="brand-mark">M<span>+</span></div><div><strong>Mercado Pro</strong><small>Gestão inteligente</small></div></div><h1 class="auth-title">Não consegui conectar.</h1><p class="auth-copy">Confira se o servidor está rodando no terminal. Depois, recarregue esta página.</p><button class="btn btn-primary" id="retry-boot">Tentar novamente</button></section></div>`;$('#retry-boot')?.addEventListener('click',boot);}
  }
  function renderAuth(setup){
    state.user=null;
    app.innerHTML=`<main class="auth-wrap"><section class="auth-card" aria-labelledby="auth-title"><div class="auth-logo"><div class="brand-mark" aria-hidden="true">M<span>+</span></div><div><strong>Mercado Pro</strong><small>Gestão de mercado · armazenamento local</small></div></div><p class="eyebrow" style="margin-top:27px">${setup?'PRIMEIRO ACESSO':'ÁREA RESTRITA'}</p><h1 id="auth-title" class="auth-title">${setup?'Seu mercado começa aqui.':'Bom ter você de volta.'}</h1><p class="auth-copy">${setup?'Crie a conta administradora. Os dados ficam no banco local desta instalação.':'Entre com seu usuário para acessar o painel de gestão.'}</p><form id="auth-form" data-auth-mode="${setup?'setup':'login'}"><div class="form-grid"><div class="field full"><label for="auth-user">Usuário de acesso</label><input id="auth-user" name="username" placeholder="${setup?'Crie um usuário':'Seu usuário'}" minlength="3" maxlength="40" autocomplete="username" required></div>${setup?'<div class="field full"><label for="auth-name">Nome de exibição</label><input id="auth-name" name="display_name" placeholder="Ex.: Jão Silva" maxlength="80" autocomplete="name" required></div>':''}<div class="field full"><label for="auth-password">Senha</label><input id="auth-password" name="password" type="password" minlength="${setup?'10':'1'}" autocomplete="${setup?'new-password':'current-password'}" placeholder="${setup?'Mínimo de 10 caracteres':'Digite sua senha'}" required></div>${setup?'<div class="field full"><label for="auth-password2">Confirme a senha</label><input id="auth-password2" name="password2" type="password" minlength="10" autocomplete="new-password" required></div>':''}</div><div class="form-actions" style="border:0;padding-top:0"><button class="btn btn-primary" type="submit" style="width:100%;min-height:48px">${setup?'Criar administrador →':'Entrar no painel →'}</button></div></form><p class="auth-foot">🔒 Senhas com hash seguro · Banco SQLite local · Sem dependências de nuvem.</p></section></main>`;
    $('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const mode=e.currentTarget.dataset.authMode;const pass=f.get('password');if(mode==='setup'&&pass!==f.get('password2')){toast('As senhas não coincidem.','error');return;}const btn=$('button[type="submit"]',e.currentTarget);btn.disabled=true;btn.textContent='Validando...';try{const d=await api(mode==='setup'?'/api/setup':'/api/login',{method:'POST',body:{username:f.get('username'),password:pass,...(mode==='setup'?{display_name:f.get('display_name')}:{})}});state.user=d.user;state.csrf=d.user.csrf_token;await loadPage('dashboard');renderApp();toast(mode==='setup'?'Administrador criado. Banco pronto para uso.':'Acesso autorizado.');}catch(err){btn.disabled=false;btn.textContent=mode==='setup'?'Criar administrador →':'Entrar no painel →';}});
  }
  function renderApp(){
    if(!state.user){renderAuth(false);return;}
    const navItem=(key)=>`<button type="button" class="nav-item ${state.page===key?'active':''}" data-nav="${key}" ${state.page===key?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icons[key]}</span><span>${pageNames[key]}</span></button>`;
    app.innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar" aria-label="Navegação principal"><div class="side-brand"><div class="brand-mark" aria-hidden="true">M<span>+</span></div><div><strong>mercado<span style="color:var(--lime)">pro</span></strong><small>INTELIGÊNCIA DE VAREJO</small></div></div><div><p class="nav-label">Operação</p><nav class="nav-stack">${['dashboard','pos','sales','products','categories','discounts','stock'].map(navItem).join('')}</nav></div><div><p class="nav-label">Gestão</p><nav class="nav-stack">${['finance','purchases','customers','settings'].map(navItem).join('')}</nav></div><div class="side-spacer"></div><div class="side-status"><span class="status-dot"></span><strong style="color:#f4f7fb">Banco local ativo</strong><br>Dados salvos neste computador.<br><span style="color:#91a4bf">Sessão protegida · 12 horas</span></div><div class="user-box"><div class="avatar">${esc(slugText(state.user.display_name))}</div><div class="user-meta"><strong>${esc(state.user.display_name)}</strong><small>${roleLabel(state.user.role)}</small></div><button class="logout-btn" type="button" data-action="logout" aria-label="Sair da conta" title="Sair">⇥</button></div></aside><div class="main-column"><header class="topbar"><div class="topbar-left"><button class="icon-button mobile-nav-toggle" type="button" data-action="toggle-nav" aria-label="Abrir menu">☰</button><div class="mobile-brand"><div class="brand-mark" aria-hidden="true">M<span>+</span></div></div><div><p class="breadcrumb">MERCADO PRO / ${esc(pageNames[state.page].toUpperCase())}</p><h1>${esc(pageNames[state.page])}</h1></div></div><div class="topbar-actions"><button class="icon-button" type="button" data-action="quick-search" aria-label="Buscar produtos" title="Buscar produtos">⌕</button><button class="btn btn-primary" type="button" data-nav="pos"><span>＋</span> Nova venda</button></div></header><main class="content" id="main" tabindex="-1">${renderPage()}</main></div></div>`;
  }
  function roleLabel(r){return ({admin:'Administrador',manager:'Gerente',cashier:'Operador de caixa'})[r]||r;}
  function head(title,desc,action=''){return `<div class="section-head"><div><p class="eyebrow">CENTRAL DE GESTÃO</p><h2>${title}</h2><p>${desc}</p></div>${action}</div>`;}
  function empty(title,desc,icon='＋'){return `<div class="empty-state"><div class="empty-illustration">${icon}</div><strong>${title}</strong><p>${desc}</p></div>`;}
  function metric(label,value,icon,accent,wash,note=''){return `<article class="metric-card" style="--accent:${accent};--wash:${wash}"><div class="metric-top"><span class="metric-label">${label}</span><span class="metric-icon" aria-hidden="true">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></article>`;}
  function pill(label,cls){return `<span class="pill ${cls}">${label}</span>`;}
  function stockPill(stock,min){return stock<=0?'<span class="stock-flag stock-out">Sem estoque</span>':stock<=min?'<span class="stock-flag stock-low">Estoque baixo</span>':'<span class="stock-flag stock-ok">Em estoque</span>';}
  function renderPage(){switch(state.page){case'dashboard':return dashboardView();case'products':return productsView();case'categories':return categoriesView();case'discounts':return discountsView();case'stock':return stockView();case'pos':return posView();case'sales':return salesView();case'finance':return financeView();case'purchases':return purchasesView();case'customers':return customersView();case'settings':return settingsView();default:return dashboardView();}}
  function chartSvg(rows){
    if(!rows||!rows.length)return `<div class="chart-empty"><strong>Sem vendas neste período</strong><span>Registre uma venda para começar a visualizar a evolução.</span></div>`;
    const vals=rows.map(x=>Number(x.revenue)||0);const max=Math.max(...vals,1);const W=640,H=200,left=8,right=8,top=12,bottom=18;const pts=vals.map((v,i)=>({x:left+(vals.length===1?(W-left-right)/2:i*(W-left-right)/(vals.length-1)),y:top+(1-v/max)*(H-top-bottom)}));const poly=pts.map(p=>`${p.x},${p.y}`).join(' ');const area=`${pts[0].x},${H-bottom} ${poly} ${pts[pts.length-1].x},${H-bottom}`;let grid='';for(let i=0;i<4;i++){const y=top+i*(H-top-bottom)/3;grid+=`<line x1="0" y1="${y}" x2="${W}" y2="${y}" stroke="#edf1f6" stroke-dasharray="4 5"/>`;}
    return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Gráfico de faturamento por dia, maior valor ${esc(brl(max))}" preserveAspectRatio="none"><title>Faturamento diário</title>${grid}<polygon points="${area}" fill="#16a875" opacity=".10"/><polyline points="${poly}" fill="none" stroke="#16a875" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/>${pts.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="${vals[i]===max?5:3}" fill="#fff" stroke="#16a875" stroke-width="2"/>`).join('')}</svg><div class="chart-labels">${[rows[0],rows[Math.floor((rows.length-1)/2)],rows[rows.length-1]].filter(Boolean).filter((x,i,a)=>a.findIndex(y=>y.day===x.day)===i).map(x=>`<span>${dateShort(x.day)}</span>`).join('')}</div>`;
  }
  function ranking(items,field='quantity',metricLabel='unidades'){if(!items||!items.length)return empty('Ainda sem movimentação','As vendas vão preencher este ranking automaticamente.','↗');const max=Math.max(...items.map(x=>Number(x[field])||0),1);return `<div class="rank-list">${items.map((x,i)=>`<div class="rank-item"><span class="rank-num">${String(i+1).padStart(2,'0')}</span><div class="rank-info"><strong>${esc(x.product_name)}</strong><div class="rank-bar"><i style="width:${Math.max(2,Number(x[field]||0)/max*100)}%"></i></div><small>${qty(x.quantity??0)} ${metricLabel}</small></div><span class="rank-value">${field==='revenue'?brl(x[field]):qty(x[field])}</span></div>`).join('')}</div>`;}
  function dashboardView(){const d=state.dashboard;if(!d)return `<div class="boot-screen">Carregando indicadores...</div>`;return `${`<section class="welcome-banner"><div class="welcome-copy"><p class="eyebrow">SEU NEGÓCIO, EM TEMPO REAL</p><h2>Boa gestão começa com visão clara.</h2><p>Produtos, caixa, estoque e resultado em um só lugar. O que precisa de atenção aparece aqui primeiro.</p><div class="welcome-actions"><button class="btn btn-lime" data-nav="pos">＋ Registrar venda</button><button class="btn btn-outline" data-nav="products">Ver produtos ↗</button></div></div><div class="welcome-stat"><strong>${d.sales_count}</strong><span>vendas no período</span></div></section>`}<div class="period-bar"><div><p class="eyebrow">RESUMO DO PERÍODO</p><span class="helper">${dateShort(d.period.from)} até ${dateShort(d.period.to)}</span></div>${dateFields()}</div><div class="grid metric-grid">${metric('Faturamento',brl(d.revenue),'↗','#138b63','#def8ed',`${d.sales_count} venda(s) concluída(s)`)}${metric('Lucro bruto estimado',brl(d.gross_profit),'◒','#4778ff','#eaf0ff',`Vendas menos custo dos produtos`)}${metric('Despesas registradas',brl(d.expenses),'↘','#d48b14','#fff2d8','Despesas lançadas manualmente')}${metric('Resultado estimado',brl(d.estimated_result),'✳',d.estimated_result<0?'#d84755':'#8258df',d.estimated_result<0?'#fff0f1':'#f1eaff','Lucro bruto menos despesas')}</div><div class="grid two-col"><section class="panel"><div class="panel-head"><div><h3>Ritmo das vendas</h3><p>Faturamento diário dentro do período selecionado</p></div>${pill('ATUALIZADO','pill-green')}</div><div class="panel-body"><div class="chart-summary"><strong>${brl(d.revenue)}</strong><span>receita no período</span><span>${brl(d.discounts)} em descontos</span></div><div class="chart-wrap">${chartSvg(d.trend)}</div></div></section><section class="panel"><div class="panel-head"><div><h3>Produtos em destaque</h3><p>Os que mais giraram no período</p></div><button class="btn btn-outline btn-sm" data-nav="sales">Ver vendas ↗</button></div><div class="panel-body">${ranking(d.top_products,'quantity','unid.')}</div></section></div><div class="grid two-col"><section class="panel"><div class="panel-head"><div><h3>Estoque pede atenção</h3><p>Itens no mínimo ou abaixo dele</p></div><button class="btn btn-outline btn-sm" data-nav="stock">Abrir estoque ↗</button></div><div class="panel-body">${d.low_stock.length?`<div class="alert-list">${d.low_stock.map(p=>`<div class="alert-row"><div class="alert-symbol" aria-hidden="true">!</div><div class="alert-text"><strong>${esc(p.name)}</strong><small>SKU ${esc(p.sku)} · mínimo ${qty(p.min_stock)} ${esc(p.unit)}</small></div><div style="text-align:right">${stockPill(p.stock,p.min_stock)}<div class="helper" style="margin-top:5px">Atual: ${qty(p.stock)} ${esc(p.unit)}</div></div></div>`).join('')}</div>`:empty('Estoque tranquilo','Nenhum produto atingiu o limite mínimo.','✓')}</div></section><section class="panel"><div class="panel-head"><div><h3>Movimentações recentes</h3><p>Últimas vendas registradas</p></div><button class="btn btn-outline btn-sm" data-nav="sales">Histórico ↗</button></div><div class="panel-body">${d.recent_sales.length?`<div class="alert-list">${d.recent_sales.map(s=>`<div class="alert-row"><div class="alert-symbol" style="background:var(--blue2);color:var(--blue)">↗</div><div class="alert-text"><strong>${esc(s.code)} · ${esc(s.customer_name||'Venda balcão')}</strong><small>${dateTime(s.created_at)} · ${esc(paymentLabel(s.payment_method))}</small></div><div style="text-align:right"><strong style="font-size:12px">${brl(s.total)}</strong><div style="margin-top:3px">${s.status==='completed'?pill('Concluída','pill-green'):pill('Cancelada','pill-red')}</div></div></div>`).join('')}</div>`:empty('Seu caixa está zerado por enquanto','A primeira venda aparecerá nesta lista.','▣')}</div></section></div><div class="grid two-col"><section class="panel"><div class="panel-head"><div><h3>Produtos com menor giro</h3><p>Itens com menos unidades vendidas no período, inclusive os sem venda</p></div><button class="btn btn-outline btn-sm" data-nav="products">Abrir catálogo ↗</button></div><div class="panel-body">${ranking(d.slow_products,'quantity','unid.')}</div></section><section class="panel"><div class="panel-head"><div><h3>Saúde da operação</h3><p>Visão rápida do que está cadastrado e parado no estoque</p></div></div><div class="panel-body"><div class="grid" style="grid-template-columns:repeat(2,minmax(0,1fr));gap:10px">${metric('Valor de custo do estoque',brl(d.stock_value),'▤','#4778ff','#eaf0ff','Custo registrado × saldo atual')}${metric('Produtos ativos',d.products_count,'▦','#138b63','#def8ed','Itens no catálogo')}${metric('Categorias',d.categories_count,'◫','#8258df','#f1eaff','Organização do catálogo')}${metric('Promoções ativas',d.active_discounts,'％','#d48b14','#fff2d8','Regras cadastradas ativas')}</div></div></section></div>`;}
  function dateFields(){return `<form class="filter-dates" id="period-filter"><label>De <input name="from" type="date" value="${esc(state.dateFrom)}" required></label><label>Até <input name="to" type="date" value="${esc(state.dateTo)}" required></label><button class="btn btn-outline btn-sm" type="submit">Aplicar</button></form>`;}
  function productThumb(p){const palettes=['#e0f7eb','#eaf0ff','#fff1dc','#f1eaff','#ffe8ed'];const emoji=({'kg':'🥬','un':'🛍️','L':'🧃','g':'🥫','pct':'📦','cx':'📦'})[p.unit]||'▦';return `<span class="product-thumb" style="--thumb:${palettes[(Number(p.id)||0)%palettes.length]}" aria-hidden="true">${emoji}</span>`;}
  function productActions(p){return `<div class="table-actions"><button class="icon-action" title="Editar ${esc(p.name)}" aria-label="Editar ${esc(p.name)}" data-action="edit-product" data-id="${p.id}">✎</button><button class="icon-action" title="Arquivar ${esc(p.name)}" aria-label="Arquivar ${esc(p.name)}" data-action="archive-product" data-id="${p.id}">⌑</button></div>`;}
  function productTable(items,showActions=true){if(!items.length)return `<tr><td colspan="7">${empty('Nenhum produto encontrado','Cadastre um produto ou ajuste sua busca.','▦')}</td></tr>`;return items.map(p=>`<tr><td><div class="product-cell">${productThumb(p)}<div><strong>${esc(p.name)}</strong><small>${esc(p.sku)}${p.barcode?' · '+esc(p.barcode):''}</small></div></div></td><td>${esc(p.category_name||'Sem categoria')}</td><td><div class="price-main">${brl(p.price)}</div>${p.effective_discount_bp?`<small style="color:#0b9567">Oferta ${qty(p.effective_discount_bp/100)}% · ${brl(p.sale_price)}</small>`:''}</td><td>${brl(p.cost)}</td><td>${qty(p.stock)} ${esc(p.unit)}</td><td>${stockPill(p.stock,p.min_stock)}</td><td>${showActions?productActions(p):`<button class="btn btn-primary btn-sm" data-action="cart-add" data-id="${p.id}">＋ Adicionar</button>`}</td></tr>`).join('');}
  function productsView(){const list=state.products.filter(p=>[p.name,p.sku,p.barcode,p.category_name].join(' ').toLowerCase().includes(state.query.toLowerCase()));return `${head('Seu catálogo, sob controle.','Edite preços e custos, organize categorias e acompanhe cada unidade.',`<button class="btn btn-primary" data-action="new-product">＋ Novo produto</button>`)}<div class="toolbar" style="margin-bottom:17px"><div class="searchbox"><input type="search" id="product-search" placeholder="Buscar nome, SKU ou código de barras..." value="${esc(state.query)}" aria-label="Buscar produto por nome, SKU ou código de barras"></div><span class="pill pill-gray">${list.length} produto(s)</span><a class="btn btn-outline" href="/api/export?type=products">Exportar CSV ↓</a></div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Produto / SKU</th><th>Categoria</th><th>Preço de venda</th><th>Custo unitário</th><th>Estoque</th><th>Status</th><th style="text-align:right">Ações</th></tr></thead><tbody>${productTable(list)}</tbody></table></div><div class="table-footer"><span>O custo é usado para estimar margem e resultado.</span><span>Moeda: BRL · Estoque com até 3 casas decimais</span></div></section>`;}
  function categoriesView(){return `${head('Categorias que fazem sentido.','Crie grupos para organizar produtos e aplicar descontos por categoria.',`<button class="btn btn-primary" data-action="new-category">＋ Nova categoria</button>`)}<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr));margin-bottom:18px">${state.categories.map(c=>`<article class="setting-card" style="padding:18px;border-top:3px solid ${esc(c.color)}"><div style="display:flex;align-items:center;justify-content:space-between;gap:10px"><span style="display:flex;align-items:center;gap:9px;font-weight:800"><span style="height:11px;width:11px;border-radius:4px;background:${esc(c.color)}"></span>${esc(c.name)}</span><span class="pill pill-gray">${c.product_count} itens</span></div><div class="action-stack" style="margin-top:17px"><button class="btn btn-outline btn-sm" data-action="edit-category" data-id="${c.id}">Editar</button>${c.name!=='Sem categoria'?`<button class="btn btn-danger btn-sm" data-action="delete-category" data-id="${c.id}">Excluir</button>`:''}</div></article>`).join('')}</div><section class="panel"><div class="panel-head"><div><h3>Visão de categorias</h3><p>Cada produto pode pertencer a uma categoria por vez.</p></div></div><div class="table-wrap"><table class="data-table" style="min-width:450px"><thead><tr><th>Categoria</th><th>Produtos ativos</th><th>Cor de identificação</th></tr></thead><tbody>${state.categories.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${c.product_count}</td><td><span style="display:inline-flex;align-items:center;gap:8px"><span style="width:14px;height:14px;background:${esc(c.color)};border-radius:4px"></span><span class="subtle">${esc(c.color)}</span></span></td></tr>`).join('')||'<tr><td colspan="3">Sem categorias.</td></tr>'}</tbody></table></div></section>`;}
  function discountsView(){const active=state.discounts.filter(d=>d.active);return `${head('Promoções sem conta de cabeça.','Descontos por produto ou categoria, com vigência opcional.',`<button class="btn btn-primary" data-action="new-discount">％ Criar promoção</button>`)}<div class="grid analytics-grid">${metric('Promoções ativas',active.length,'％','#138b63','#def8ed','Promoções não são somadas entre si')}${metric('Maior desconto ativo',active.length?`${Math.max(...active.map(d=>d.percent_bp))/100}%`:'0%','✦','#8258df','#f1eaff','Prevalece a maior oferta válida')}${metric('Ofertas cadastradas',state.discounts.length,'▤','#4778ff','#eaf0ff','Inclui promoções pausadas')}</div><section class="panel"><div class="panel-head"><div><h3>Regras de desconto</h3><p>Na venda, a maior promoção válida é aplicada. Descontos não acumulam.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Promoção</th><th>Aplicação</th><th>Desconto</th><th>Vigência</th><th>Status</th><th>Ações</th></tr></thead><tbody>${state.discounts.length?state.discounts.map(d=>`<tr><td><strong>${esc(d.name)}</strong><div class="helper">ID #${d.id}</div></td><td>${pill(d.target_type==='product'?'Produto':'Categoria',d.target_type==='product'?'pill-blue':'pill-purple')}<div style="margin-top:5px">${esc(d.target_name||'Item não encontrado')}</div></td><td><strong style="font-size:15px;color:#0a9567">${(d.percent_bp/100).toLocaleString('pt-BR')}%</strong></td><td><span class="subtle">${d.starts_at?dateShort(d.starts_at):'Desde já'}</span><br><span class="subtle">até ${d.ends_at?dateShort(d.ends_at):'sem data final'}</span></td><td>${d.active?pill('Ativa','pill-green'):pill('Pausada','pill-gray')}</td><td><div class="actions-cell"><button class="btn btn-outline btn-sm" data-action="toggle-discount" data-id="${d.id}" data-active="${d.active?0:1}">${d.active?'Pausar':'Ativar'}</button><button class="btn btn-danger btn-sm" data-action="delete-discount" data-id="${d.id}">Excluir</button></div></td></tr>`).join(''):`<tr><td colspan="6">${empty('Nenhuma promoção por enquanto','Crie uma regra por produto ou categoria.','％')}</td></tr>`}</tbody></table></div></section>`;}
  function stockView(){const d=state.stock;if(!d)return `<div class="boot-screen">Carregando estoque...</div>`;const list=d.products;return `${head('Estoque no mundo real.','Entradas, ajustes, níveis mínimos e trilha de auditoria por produto.',`<button class="btn btn-primary" data-action="stock-move">＋ Movimentar estoque</button>`)}<div class="toolbar" style="margin-bottom:17px"><div class="searchbox"><input type="search" id="stock-search" placeholder="Buscar produto no estoque..." aria-label="Buscar no estoque"></div><button class="btn btn-outline" data-action="toggle-low">⚑ ${state.showLow?'Mostrar todos':'Só estoque baixo'}</button><a class="btn btn-outline" href="/api/export?type=stock">Exportar movimentos ↓</a></div><section class="panel" style="margin-bottom:18px"><div class="panel-head"><div><h3>Posição atual</h3><p>Use ajuste para definir a quantidade física contada.</p></div><span class="pill pill-gray">${list.length} produtos</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Produto</th><th>Categoria</th><th>Quantidade atual</th><th>Estoque mínimo</th><th>Sinal</th><th>Custo unitário</th></tr></thead><tbody>${list.length?list.map(p=>`<tr><td><div class="product-cell">${productThumb(p)}<div><strong>${esc(p.name)}</strong><small>${esc(p.sku)}</small></div></div></td><td>${esc(p.category_name||'Sem categoria')}</td><td><strong>${qty(p.stock)} ${esc(p.unit)}</strong></td><td>${qty(p.min_stock)} ${esc(p.unit)}</td><td>${stockPill(p.stock,p.min_stock)}</td><td>${brl(p.unit_cost)}</td></tr>`).join(''):`<tr><td colspan="6">${empty('Estoque vazio','Cadastre produtos para acompanhar as quantidades.','▤')}</td></tr>`}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h3>Trilha de movimentações</h3><p>Registro cronológico de entradas, saídas e ajustes.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Produto</th><th>Tipo</th><th>Variação</th><th>Antes → depois</th><th>Motivo</th><th>Usuário</th></tr></thead><tbody>${d.movements.length?d.movements.map(m=>`<tr><td class="no-wrap">${dateTime(m.created_at)}</td><td><strong>${esc(m.product_name)}</strong><div class="helper">${esc(m.sku)}</div></td><td>${pill(moveLabel(m.kind),moveClass(m.kind))}</td><td class="${m.quantity<0?'margin-negative':'margin-positive'}">${m.quantity>0?'+':''}${qty(m.quantity)}</td><td>${qty(m.before_milli)} → <strong>${qty(m.after_milli)}</strong></td><td>${esc(m.note)}</td><td>${esc(m.username||'Sistema')}</td></tr>`).join(''):`<tr><td colspan="7">${empty('Ainda sem movimentações','As alterações de estoque ficarão registradas aqui.','↔')}</td></tr>`}</tbody></table></div><div class="table-footer"><span>Movimentações não são apagadas ao editar um produto.</span><span>Últimas 150 entradas</span></div></section>`;}
  function moveLabel(v){return ({entry:'Entrada',sale:'Venda',adjustment:'Ajuste',return:'Devolução',cancellation:'Estorno',purchase:'Compra'})[v]||v;}
  function moveClass(v){return ({entry:'pill-green',sale:'pill-blue',adjustment:'pill-yellow',return:'pill-purple',cancellation:'pill-red',purchase:'pill-green'})[v]||'pill-gray';}
  function posView(){const cartTotal=state.cart.reduce((sum,c)=>sum+c.currentPrice*c.quantity,0);const cartQty=state.cart.reduce((sum,c)=>sum+c.quantity,0);return `${head('Caixa aberto. Vamos vender?','Selecione os produtos, confira o desconto atual e finalize a venda.',`<span class="pill pill-green">● Caixa local</span>`)}<div class="cart-layout"><section><div class="toolbar" style="margin-bottom:13px"><div class="searchbox"><input type="search" id="pos-search" placeholder="Buscar produto ou bipar código de barras..." aria-label="Buscar produto para venda" autofocus></div><span class="pill pill-gray">${state.products.length} itens no catálogo</span></div><div id="pos-product-list" class="cart-products">${posProductItems(state.products.filter(p=>p.stock>0).slice(0,20))}</div></section><section class="cart-box"><h3>Resumo da venda <span class="pill pill-gray" style="float:right">${cartQty} un.</span></h3><div id="cart-items">${cartItemsView()}</div><div class="cart-total"><div><span>Total a receber</span><div class="helper">Descontos válidos já calculados</div></div><strong>${brl(cartTotal)}</strong></div><form id="checkout-form"><div class="form-grid" style="margin-top:16px"><div class="field full"><label for="pos-customer">Cliente (opcional)</label><select name="customer_id" id="pos-customer"><option value="">Venda balcão</option>${state.customers.map(c=>`<option value="${c.id}">${esc(c.name)}${c.phone?' · '+esc(c.phone):''}</option>`).join('')}</select></div><div class="field full"><label for="pos-payment">Forma de pagamento</label><select name="payment_method" id="pos-payment" required><option value="pix">Pix</option><option value="dinheiro">Dinheiro</option><option value="credito">Cartão de crédito</option><option value="debito">Cartão de débito</option><option value="vale">Vale-alimentação/refeição</option><option value="outro">Outro</option></select></div><div class="field full"><label for="pos-notes">Observações (opcional)</label><input name="notes" id="pos-notes" maxlength="500" placeholder="Ex.: caixa 01"></div></div><button class="btn btn-primary" type="submit" style="width:100%;margin-top:16px;min-height:49px" ${state.cart.length?'':'disabled'}>✓ Finalizar venda · ${brl(cartTotal)}</button><button class="btn btn-outline" type="button" data-action="clear-cart" style="width:100%;margin-top:8px" ${state.cart.length?'':'disabled'}>Limpar carrinho</button></form><p class="helper" style="margin:13px 0 0">O preço, desconto e saldo são validados novamente pelo servidor ao confirmar.</p></section></div>`;}
  function posProductItems(items){if(!items.length)return empty('Nenhum produto disponível','Cadastre itens ou reponha o estoque.','▦');return items.map(p=>`<article class="cart-product">${productThumb(p)}<div class="cart-product-info"><strong>${esc(p.name)}</strong><small>${brl(p.sale_price)}${p.effective_discount_bp?` · ${p.effective_discount_bp/100}% OFF`:''} · ${qty(p.stock)} ${esc(p.unit)} disponíveis</small></div><button type="button" data-action="cart-add" data-id="${p.id}" aria-label="Adicionar ${esc(p.name)} ao carrinho">＋</button></article>`).join('');}
  function cartItemsView(){if(!state.cart.length)return empty('Carrinho vazio','Pesquise e adicione produtos para montar a venda.','▣');return state.cart.map(c=>`<div class="cart-line"><div style="min-width:0;flex:1"><strong>${esc(c.name)}</strong><div class="helper">${brl(c.currentPrice)} por ${esc(c.unit)}${c.discount?` · ${c.discount/100}% off`:''}</div><div class="action-stack" style="margin-top:5px;align-items:center"><button type="button" class="btn btn-outline btn-sm" data-action="cart-qty" data-id="${c.id}" data-delta="-1" aria-label="Diminuir ${esc(c.name)}">−</button><label class="helper" style="display:flex;align-items:center;gap:4px"><span class="visually-hidden">Quantidade de ${esc(c.name)}</span><input aria-label="Quantidade de ${esc(c.name)}" type="number" min="0.001" max="${c.stock}" step="${['kg','g','L','ml','m'].includes(c.unit)?'0.001':'1'}" value="${c.quantity}" data-cart-quantity="${c.id}" style="width:75px;border:1px solid var(--line);border-radius:8px;padding:5px"></label><button type="button" class="btn btn-outline btn-sm" data-action="cart-qty" data-id="${c.id}" data-delta="1" aria-label="Aumentar ${esc(c.name)}">＋</button><button type="button" class="btn btn-danger btn-sm" data-action="cart-remove" data-id="${c.id}">Remover</button></div></div><strong>${brl(c.quantity*c.currentPrice)}</strong></div>`).join('');}
  function salesView(){return `${head('Cada venda, rastreável.','Consulte, confira itens e cancele uma venda com estorno de estoque.',`<a class="btn btn-outline" href="/api/export?type=sales">Exportar CSV ↓</a>`)}<div class="period-bar">${dateFields()}<span class="pill pill-gray">${state.sales.length} venda(s) no período</span></div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Venda</th><th>Data e hora</th><th>Cliente</th><th>Pagamento</th><th>Subtotal</th><th>Desconto</th><th>Total</th><th>Status</th><th>Ações</th></tr></thead><tbody>${state.sales.length?state.sales.map(s=>`<tr><td><strong>${esc(s.code)}</strong></td><td>${dateTime(s.created_at)}</td><td>${esc(s.customer_name||'Venda balcão')}</td><td>${esc(paymentLabel(s.payment_method))}</td><td>${brl(s.subtotal)}</td><td>${brl(s.discount)}</td><td><strong>${brl(s.total)}</strong></td><td>${s.status==='completed'?pill('Concluída','pill-green'):pill('Cancelada','pill-red')}</td><td><div class="actions-cell"><button class="btn btn-outline btn-sm" data-action="sale-details" data-id="${s.id}">Detalhes</button>${s.status==='completed'&&state.user.role!=='cashier'?`<button class="btn btn-danger btn-sm" data-action="cancel-sale" data-id="${s.id}">Cancelar</button>`:''}</div></td></tr>`).join(''):`<tr><td colspan="9">${empty('Nenhuma venda neste período','Altere o período ou registre sua primeira venda.','↗')}</td></tr>`}</tbody></table></div></section>`;}
  function paymentLabel(p){return ({dinheiro:'Dinheiro',pix:'Pix',credito:'Crédito',debito:'Débito',vale:'Vale',outro:'Outro'})[p]||p;}
  function financeView(){const a=state.analytics;if(!a)return `<div class="boot-screen">Calculando indicadores...</div>`;return `${head('O número por trás do balcão.','Acompanhe custo, margem, descontos e despesas registradas.',`<button class="btn btn-primary" data-action="new-expense">＋ Lançar despesa</button>`)}<div class="period-bar">${dateFields()}<a class="btn btn-outline" href="/api/export?type=expenses">Exportar despesas ↓</a></div><div class="grid metric-grid">${metric('Receita líquida de descontos',brl(a.revenue),'↗','#138b63','#def8ed',`${a.orders} venda(s) concluída(s)`)}${metric('Custo dos produtos vendidos',brl(a.cost),'▤','#4778ff','#eaf0ff','Custo registrado no momento da venda')}${metric('Margem bruta',`${a.margin_pct.toLocaleString('pt-BR')}%`,'◒','#8258df','#f1eaff',`Lucro bruto: ${brl(a.gross_profit)}`)}${metric('Resultado estimado',brl(a.estimated_result),'✳',a.estimated_result<0?'#d84755':'#138b63',a.estimated_result<0?'#fff0f1':'#def8ed',`Após ${brl(a.expenses)} em despesas lançadas`)}</div><div class="modal-note warning">Importante: este é um painel gerencial estimado, não uma contabilidade oficial. Ele usa custo atual registrado nos produtos para vendas novas e custo congelado em vendas já realizadas. Impostos, taxas de cartão, perdas não registradas e retiradas só entram se você os registrar.</div><div class="grid split-panels"><section class="panel"><div class="panel-head"><div><h3>Faturamento por categoria</h3><p>Receita dos itens vendidos no período</p></div></div><div class="table-wrap"><table class="data-table" style="min-width:410px"><thead><tr><th>Categoria</th><th>Quantidade</th><th>Receita</th><th>Margem bruta</th></tr></thead><tbody>${a.by_category.length?a.by_category.map(r=>`<tr><td><strong>${esc(r.category)}</strong></td><td>${qty(r.quantity)}</td><td>${brl(r.revenue)}</td><td class="${r.revenue-r.cost>=0?'margin-positive':'margin-negative'}">${brl(r.revenue-r.cost)}</td></tr>`).join(''):`<tr><td colspan="4">${empty('Sem vendas agrupadas','As categorias aparecerão aqui após as vendas.','◫')}</td></tr>`}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h3>Formas de pagamento</h3><p>Volume e faturamento por método</p></div></div><div class="panel-body">${a.payments.length?`<div class="rank-list">${a.payments.map((p,i)=>`<div class="rank-item"><span class="rank-num">${i+1}</span><div class="rank-info"><strong>${esc(paymentLabel(p.payment_method))}</strong><small>${p.count} venda(s)</small><div class="rank-bar"><i style="width:${Math.max(2,p.total/Math.max(...a.payments.map(x=>x.total),1)*100)}%"></i></div></div><span class="rank-value">${brl(p.total)}</span></div>`).join('')}</div>`:empty('Sem pagamentos registrados','Finalize uma venda para começar.','▣')}</div></section></div><section class="panel" style="margin-top:18px"><div class="panel-head"><div><h3>Despesas operacionais</h3><p>Registros manuais considerados no resultado estimado.</p></div><span class="pill pill-yellow">${brl(a.expenses)} no período</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Categoria</th><th>Descrição</th><th>Pagamento</th><th>Valor</th><th>Ação</th></tr></thead><tbody>${state.expenses.length?state.expenses.map(e=>`<tr><td>${dateShort(e.expense_date)}</td><td>${esc(e.category)}</td><td><strong>${esc(e.description)}</strong></td><td>${esc(paymentLabel(e.payment_method))}</td><td><strong>${brl(e.amount)}</strong></td><td>${state.user.role!=='cashier'?`<button class="btn btn-danger btn-sm" data-action="delete-expense" data-id="${e.id}">Excluir</button>`:'-'}</td></tr>`).join(''):`<tr><td colspan="6">${empty('Nenhuma despesa lançada','Cadastre aluguel, energia, frete e outros custos operacionais.','↘')}</td></tr>`}</tbody></table></div></section>`;}
  function purchasesView(){return `${head('Reposição com rastreio.','Cadastre fornecedores, monte pedidos e receba mercadorias no estoque.',`<button class="btn btn-primary" data-action="new-purchase">＋ Novo pedido</button>`)}<div class="grid metric-grid">${metric('Fornecedores ativos',state.suppliers.length,'⇄','#138b63','#def8ed','Base de contatos cadastrados')}${metric('Pedidos em rascunho',state.purchases.filter(p=>p.status==='draft').length,'▤','#4778ff','#eaf0ff','Aguardando recebimento')}${metric('Pedidos recebidos',state.purchases.filter(p=>p.status==='received').length,'✓','#8258df','#f1eaff','Estoque já atualizado')}${metric('Compras em rascunho',brl(state.purchases.filter(p=>p.status==='draft').reduce((s,p)=>s+p.total,0)),'R$','#d48b14','#fff2d8','Não entra como despesa financeira')}</div><section class="panel" style="margin-bottom:18px"><div class="panel-head"><div><h3>Pedidos de compra</h3><p>Receber um pedido soma os itens ao estoque e atualiza o último custo unitário.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Pedido</th><th>Fornecedor</th><th>Data</th><th>Itens</th><th>Total estimado</th><th>Status</th><th>Ação</th></tr></thead><tbody>${state.purchases.length?state.purchases.map(p=>`<tr><td><strong>${esc(p.code)}</strong></td><td>${esc(p.supplier_name||'Não associado')}</td><td>${dateShort(p.created_at)}</td><td>${p.items.length}</td><td><strong>${brl(p.total)}</strong></td><td>${p.status==='draft'?pill('Rascunho','pill-yellow'):p.status==='received'?pill('Recebido','pill-green'):pill('Cancelado','pill-red')}</td><td><div class="actions-cell"><button class="btn btn-outline btn-sm" data-action="purchase-details" data-id="${p.id}">Detalhes</button>${p.status==='draft'&&state.user.role!=='cashier'?`<button class="btn btn-primary btn-sm" data-action="receive-purchase" data-id="${p.id}">Receber</button>`:''}</div></td></tr>`).join(''):`<tr><td colspan="7">${empty('Nenhum pedido ainda','Crie um pedido de compra e registre a chegada.','⇄')}</td></tr>`}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h3>Fornecedores</h3><p>Contatos para facilitar a reposição.</p></div><button class="btn btn-outline btn-sm" data-action="new-supplier">＋ Adicionar fornecedor</button></div><div class="table-wrap"><table class="data-table" style="min-width:600px"><thead><tr><th>Fornecedor</th><th>Contato</th><th>Telefone</th><th>E-mail</th><th>Documento</th></tr></thead><tbody>${state.suppliers.length?state.suppliers.map(s=>`<tr><td><strong>${esc(s.name)}</strong><div class="helper">${esc(s.notes||'')}</div></td><td>${esc(s.contact||'—')}</td><td>${esc(s.phone||'—')}</td><td>${esc(s.email||'—')}</td><td>${esc(s.document||'—')}</td></tr>`).join(''):`<tr><td colspan="5">${empty('Sem fornecedores cadastrados','Adicione seus principais distribuidores.','⇄')}</td></tr>`}</tbody></table></div></section>`;}
  function customersView(){return `${head('Relacionamento sem papelada.','Organize os clientes e vincule uma venda ao cadastro quando fizer sentido.',`<button class="btn btn-primary" data-action="new-customer">＋ Novo cliente</button>`)}<div class="toolbar" style="margin-bottom:17px"><div class="searchbox"><input type="search" id="customer-search" placeholder="Buscar nome, telefone ou documento..." aria-label="Buscar cliente"></div><span class="pill pill-gray">${state.customers.length} cadastro(s)</span></div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>Telefone</th><th>E-mail</th><th>Documento</th><th>Observações</th><th>Cadastro</th></tr></thead><tbody>${state.customers.length?state.customers.filter(c=>[c.name,c.phone,c.document,c.email].join(' ').toLowerCase().includes(state.query.toLowerCase())).map(c=>`<tr><td><div class="product-cell"><span class="avatar" style="background:#e8e1ff;color:#6244b5">${esc(slugText(c.name))}</span><div><strong>${esc(c.name)}</strong><small>ID #${c.id}</small></div></div></td><td>${esc(c.phone||'—')}</td><td>${esc(c.email||'—')}</td><td>${esc(c.document||'—')}</td><td>${esc(c.notes||'—')}</td><td>${dateShort(c.created_at)}</td></tr>`).join(''):`<tr><td colspan="6">${empty('Nenhum cliente encontrado','Cadastre um cliente ou limpe a busca.','♙')}</td></tr>`}</tbody></table></div></section>`;}
  function settingsView(){return `${head('A casa das configurações.','Cuide do acesso, exporte dados e faça cópias de segurança.',``)}<div class="grid settings-grid"><section class="setting-card"><p class="eyebrow">PROTEÇÃO DE DADOS</p><h3>Backup completo do banco</h3><p>Baixa uma cópia consistente do SQLite com produtos, vendas, usuários, estoque e histórico. Guarde-a em outro local seguro.</p><div class="action-stack"><a class="btn btn-primary" href="/api/backup">↓ Baixar backup SQLite</a></div></section><section class="setting-card"><p class="eyebrow">PORTABILIDADE</p><h3>Exportação para planilhas</h3><p>Arquivos CSV compatíveis com Excel e LibreOffice. Os valores monetários são exportados em centavos para não perder precisão.</p><div class="action-stack"><a class="btn btn-outline" href="/api/export?type=products">Produtos CSV</a><a class="btn btn-outline" href="/api/export?type=sales">Vendas CSV</a><a class="btn btn-outline" href="/api/export?type=stock">Estoque CSV</a><a class="btn btn-outline" href="/api/export?type=expenses">Despesas CSV</a></div></section><section class="setting-card"><p class="eyebrow">CONTROLE DE ACESSO</p><h3>Usuários da equipe</h3><p>Crie logins individuais para administradores, gerentes e operadores de caixa. Cada operação registra quem a executou.</p>${state.user.role==='admin'?`<button class="btn btn-primary" data-action="new-user">＋ Criar usuário</button><div class="table-wrap" style="margin-top:16px"><table class="data-table" style="min-width:340px"><thead><tr><th>Usuário</th><th>Perfil</th><th>Status</th></tr></thead><tbody>${state.users.map(u=>`<tr><td><strong>${esc(u.display_name)}</strong><div class="helper">@${esc(u.username)}</div></td><td>${esc(roleLabel(u.role))}</td><td>${u.active?pill('Ativo','pill-green'):pill('Inativo','pill-red')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="mini-note">Somente o administrador pode gerenciar contas de usuário.</div>`}</section><section class="setting-card"><p class="eyebrow">AUDITORIA</p><h3>Últimas operações</h3><p>Rastreie alterações de catálogo, promoções, vendas e estoque. O histórico está disponível apenas ao administrador.</p>${state.user.role==='admin'?`<button class="btn btn-outline" data-action="view-audit">Ver registro de auditoria ↗</button>`:`<div class="mini-note">Sem permissão para consultar auditoria.</div>`}</section><section class="setting-card"><p class="eyebrow">SESSÃO ATUAL</p><h3>${esc(state.user.display_name)}</h3><p>Usuário <strong>@${esc(state.user.username)}</strong> · perfil ${roleLabel(state.user.role)}. A senha nunca é armazenada em texto puro.</p><div class="action-stack"><button class="btn btn-outline" data-action="logout">Sair da conta</button></div></section><section class="setting-card"><p class="eyebrow">INFORMAÇÃO IMPORTANTE</p><h3>Uso local e limites fiscais</h3><p>Esta instalação é um painel gerencial local. Emissão de NFC-e/NF-e, TEF, balanças, leitor fiscal e obrigações tributárias exigem integração e homologação específicas, não incluídas.</p><div class="mini-note">Servidor configurado para aceitar conexões somente do próprio computador por padrão. Não o exponha diretamente à internet.</div></section></div>`;}

  async function loadPage(page){
    state.page=page;
    const tasks=[];
    if(page==='dashboard'){tasks.push(api(`/api/dashboard?from=${state.dateFrom}&to=${state.dateTo}`).then(x=>state.dashboard=x));}
    if(['products','pos','categories','discounts','stock','purchases','customers','sales','finance','settings'].includes(page)){
      if(['products','pos','stock','purchases','discounts','categories'].includes(page))tasks.push(api('/api/products').then(x=>state.products=x));
      if(['products','pos','categories','discounts'].includes(page))tasks.push(api('/api/categories').then(x=>state.categories=x));
      if(['discounts'].includes(page))tasks.push(api('/api/discounts').then(x=>state.discounts=x));
      if(page==='stock')tasks.push(api('/api/stock'+(state.showLow?'?low=1':'')).then(x=>state.stock=x));
      if(page==='pos'){
        tasks.push(api('/api/customers').then(x=>state.customers=x));
      }
      if(page==='sales')tasks.push(api(`/api/sales?from=${state.dateFrom}&to=${state.dateTo}`).then(x=>state.sales=x));
      if(page==='finance'){
        tasks.push(api(`/api/analytics?from=${state.dateFrom}&to=${state.dateTo}`).then(x=>state.analytics=x));
        tasks.push(api(`/api/expenses?from=${state.dateFrom}&to=${state.dateTo}`).then(x=>state.expenses=x));
      }
      if(page==='purchases'){
        tasks.push(api('/api/purchases').then(x=>state.purchases=x));tasks.push(api('/api/suppliers').then(x=>state.suppliers=x));
      }
      if(page==='customers')tasks.push(api('/api/customers').then(x=>state.customers=x));
      if(page==='settings'&&state.user.role==='admin')tasks.push(api('/api/users').then(x=>state.users=x));
    }
    await Promise.all(tasks);
  }
  async function navigate(page){if(!pageNames[page])return;state.query='';const side=$('#sidebar');if(side)side.classList.remove('open');try{await loadPage(page);renderApp();$('#main')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'});}catch(e){if(state.user)renderApp();}}
  function modalOpen(title,html,kicker='MERCADO PRO'){ $('#modal-title').textContent=title;$('#modal-kicker').textContent=kicker;modalContent.innerHTML=html;if(!modal.open)modal.showModal();const first=$('input:not([type=hidden]),select,textarea,button',modalContent);first?.focus({preventScroll:true});}
  function modalClose(){if(modal.open)modal.close();modalContent.innerHTML='';}
  function hiddenId(id){return id?`<input type="hidden" name="id" value="${id}">`:'';}
  function categoryOptions(sel){return `<option value="">Sem categoria</option>${state.categories.map(c=>`<option value="${c.id}" ${String(sel??'')===String(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}`;}
  function productOptions(sel){return `<option value="">Selecione um produto</option>${state.products.map(p=>`<option value="${p.id}" ${String(sel??'')===String(p.id)?'selected':''}>${esc(p.name)} · ${esc(p.sku)} · estoque ${qty(p.stock)} ${esc(p.unit)}</option>`).join('')}`;}
  function formActions(cancel='Cancelar',submit='Salvar'){return `<div class="form-actions"><button type="button" class="btn btn-outline" data-close-modal>${cancel}</button><button type="submit" class="btn btn-primary">${submit}</button></div>`;}
  function productForm(p=null){modalOpen(p?'Editar produto':'Cadastrar produto',`<form id="product-form" data-id="${p?.id||''}"><div class="form-grid"><div class="field"><label for="p-name">Nome do produto *</label><input id="p-name" name="name" required maxlength="150" value="${esc(p?.name||'')}" placeholder="Ex.: Arroz tipo 1 5 kg"></div><div class="field"><label for="p-sku">SKU / código interno *</label><input id="p-sku" name="sku" required maxlength="60" value="${esc(p?.sku||'')}" placeholder="Ex.: MER-001"></div><div class="field"><label for="p-barcode">Código de barras</label><input id="p-barcode" name="barcode" maxlength="80" value="${esc(p?.barcode||'')}" placeholder="EAN / GTIN (opcional)"></div><div class="field"><label for="p-category">Categoria</label><select id="p-category" name="category_id">${categoryOptions(p?.category_id)}</select></div><div class="field"><label for="p-unit">Unidade *</label><select id="p-unit" name="unit">${['un','kg','g','L','ml','pct','cx','fardo','m'].map(u=>`<option ${String(p?.unit||'un')===u?'selected':''} value="${u}">${u==='un'?'Unidade':u==='kg'?'Quilograma':u==='g'?'Grama':u==='L'?'Litro':u==='ml'?'Mililitro':u==='pct'?'Pacote':u==='cx'?'Caixa':u==='fardo'?'Fardo':'Metro'} (${u})</option>`).join('')}</select></div><div class="field"><label for="p-cost">Custo unitário (R$) *</label><input id="p-cost" name="cost" type="number" min="0" max="9999999" step="0.01" required value="${esc(p?.cost??'0.00')}"></div><div class="field"><label for="p-price">Preço de venda (R$) *</label><input id="p-price" name="price" type="number" min="0" max="9999999" step="0.01" required value="${esc(p?.price??'0.00')}"></div>${p?`<div class="field"><label for="p-stock-read">Estoque atual</label><input id="p-stock-read" value="${qty(p.stock)} ${esc(p.unit)}" readonly><span class="hint">Altere a quantidade na tela Estoque, mantendo o histórico.</span></div>`:`<div class="field"><label for="p-stock">Estoque inicial</label><input id="p-stock" name="stock" type="number" min="0" step="0.001" value="0"></div>`}<div class="field"><label for="p-min">Estoque mínimo</label><input id="p-min" name="min_stock" type="number" min="0" step="0.001" value="${esc(p?.min_stock??'0')}"></div><div class="field full"><label for="p-description">Descrição / observações</label><textarea id="p-description" name="description" maxlength="1000" placeholder="Marca, tamanho, observações internas...">${esc(p?.description||'')}</textarea></div></div>${formActions('Cancelar',p?'Salvar alterações':'Cadastrar produto')}</form>`);}
  function categoryForm(c=null){modalOpen(c?'Editar categoria':'Criar categoria',`<form id="category-form" data-id="${c?.id||''}"><div class="form-grid"><div class="field full"><label for="c-name">Nome da categoria *</label><input id="c-name" name="name" maxlength="80" required value="${esc(c?.name||'')}" placeholder="Ex.: Hortifruti"></div><div class="field full"><label for="c-color">Cor de identificação</label><input id="c-color" name="color" type="color" value="${esc(c?.color||'#32d583')}" style="height:48px;padding:4px"></div></div>${formActions('Cancelar',c?'Salvar categoria':'Criar categoria')}</form>`);}
  function discountForm(){modalOpen('Criar regra de desconto',`<form id="discount-form"><div class="form-grid"><div class="field full"><label for="d-name">Nome da promoção *</label><input id="d-name" name="name" required maxlength="100" placeholder="Ex.: Semana da limpeza"></div><div class="field"><label for="d-type">Aplicar a *</label><select id="d-type" name="target_type"><option value="product">Produto específico</option><option value="category">Categoria inteira</option></select></div><div class="field"><label for="d-target">Alvo *</label><select id="d-target" name="target_id" required>${productOptions('')}</select></div><div class="field full"><label for="d-percent">Desconto (%) *</label><input id="d-percent" name="percent" type="number" min="0.01" max="99" step="0.01" required placeholder="Ex.: 15"><span class="hint">Até 99%. A oferta válida mais alta vence, sem acumular descontos.</span></div><div class="field"><label for="d-start">Começa em</label><input id="d-start" name="starts_at" type="date"></div><div class="field"><label for="d-end">Termina em</label><input id="d-end" name="ends_at" type="date"></div></div>${formActions('Cancelar','Criar promoção')}</form>`);}
  function stockForm(){modalOpen('Movimentar estoque',`<div class="modal-note">Entrada e devolução somam unidades. Ajuste físico define o estoque final contado e registra a diferença.</div><form id="stock-form"><div class="form-grid"><div class="field full"><label for="st-product">Produto *</label><select id="st-product" name="product_id" required>${productOptions('')}</select></div><div class="field"><label for="st-kind">Tipo de movimentação *</label><select id="st-kind" name="kind"><option value="entry">Entrada manual</option><option value="adjustment">Ajuste de contagem física</option><option value="return">Devolução ao estoque</option></select></div><div class="field"><label for="st-qty" id="st-qty-label">Quantidade a adicionar *</label><input id="st-qty" name="quantity" type="number" min="0" step="0.001" required value="1"></div><div class="field full"><label for="st-note">Motivo *</label><input id="st-note" name="note" required maxlength="200" placeholder="Ex.: Recebimento, conferência semanal..."></div></div>${formActions('Cancelar','Salvar movimentação')}</form>`);}
  function expenseForm(){modalOpen('Lançar despesa',`<form id="expense-form"><div class="form-grid"><div class="field"><label for="e-category">Categoria *</label><select name="category" id="e-category" required>${['Aluguel','Energia','Água','Internet/telefone','Frete','Manutenção','Salários','Material de limpeza','Taxas bancárias','Impostos','Marketing','Outros'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label for="e-amount">Valor (R$) *</label><input id="e-amount" name="amount" type="number" min="0.01" step="0.01" required placeholder="0,00"></div><div class="field full"><label for="e-desc">Descrição *</label><input id="e-desc" name="description" required maxlength="180" placeholder="Ex.: Conta de energia de outubro"></div><div class="field"><label for="e-date">Data *</label><input id="e-date" name="expense_date" type="date" value="${today()}" required></div><div class="field"><label for="e-payment">Pagamento</label><select id="e-payment" name="payment_method"><option value="pix">Pix</option><option value="dinheiro">Dinheiro</option><option value="credito">Cartão de crédito</option><option value="debito">Cartão de débito</option><option value="boleto">Boleto</option><option value="outro">Outro</option></select></div><div class="field full"><label for="e-notes">Observações</label><textarea id="e-notes" name="notes" maxlength="500"></textarea></div></div>${formActions('Cancelar','Registrar despesa')}</form>`);}
  function supplierForm(){modalOpen('Cadastrar fornecedor',`<form id="supplier-form"><div class="form-grid"><div class="field full"><label for="s-name">Razão social / nome *</label><input id="s-name" name="name" required maxlength="150"></div><div class="field"><label for="s-doc">CNPJ/CPF</label><input id="s-doc" name="document" maxlength="30"></div><div class="field"><label for="s-contact">Pessoa de contato</label><input id="s-contact" name="contact" maxlength="120"></div><div class="field"><label for="s-phone">Telefone</label><input id="s-phone" name="phone" maxlength="40"></div><div class="field"><label for="s-email">E-mail</label><input id="s-email" name="email" type="email" maxlength="150"></div><div class="field full"><label for="s-notes">Observações</label><textarea id="s-notes" name="notes" maxlength="500"></textarea></div></div>${formActions('Cancelar','Salvar fornecedor')}</form>`);}
  function customerForm(){modalOpen('Cadastrar cliente',`<form id="customer-form"><div class="form-grid"><div class="field full"><label for="cu-name">Nome completo *</label><input id="cu-name" name="name" required maxlength="150"></div><div class="field"><label for="cu-phone">Telefone</label><input id="cu-phone" name="phone" maxlength="40" autocomplete="tel"></div><div class="field"><label for="cu-email">E-mail</label><input id="cu-email" name="email" type="email" maxlength="150" autocomplete="email"></div><div class="field full"><label for="cu-doc">CPF / documento</label><input id="cu-doc" name="document" maxlength="30"></div><div class="field full"><label for="cu-notes">Observações</label><textarea id="cu-notes" name="notes" maxlength="500"></textarea></div></div>${formActions('Cancelar','Salvar cliente')}</form>`);}
  function userForm(){modalOpen('Adicionar acesso à equipe',`<form id="user-form"><div class="form-grid"><div class="field"><label for="u-name">Nome de exibição *</label><input id="u-name" name="display_name" required maxlength="80"></div><div class="field"><label for="u-username">Usuário *</label><input id="u-username" name="username" required minlength="3" maxlength="40" autocomplete="off"></div><div class="field"><label for="u-role">Perfil *</label><select id="u-role" name="role"><option value="cashier">Operador de caixa</option><option value="manager">Gerente</option><option value="admin">Administrador</option></select></div><div class="field"><label for="u-password">Senha inicial *</label><input id="u-password" name="password" type="password" required minlength="10" autocomplete="new-password"><span class="hint">Mínimo de 10 caracteres.</span></div></div><div class="modal-note warning" style="margin-top:16px">Compartilhe a senha com segurança. Este aplicativo não possui um fluxo de recuperação de senha por e-mail.</div>${formActions('Cancelar','Criar usuário')}</form>`);}
  function purchaseForm(){modalOpen('Novo pedido de compra',`<form id="purchase-form"><div class="form-grid"><div class="field full"><label for="po-supplier">Fornecedor</label><select id="po-supplier" name="supplier_id"><option value="">Sem fornecedor associado</option>${state.suppliers.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field full"><label for="po-note">Observações</label><input id="po-note" name="notes" maxlength="500" placeholder="Número do pedido do fornecedor, previsão..."></div></div><div class="modal-note" style="margin-top:16px">Adicione os itens. O pedido será criado como rascunho. O estoque só muda quando você clicar em <strong>Receber</strong>.</div><div id="purchase-lines"></div><button type="button" class="btn btn-outline" data-action="add-purchase-line" style="margin-top:12px">＋ Adicionar item</button>${formActions('Cancelar','Criar pedido')}</form>`);addPurchaseLine();}
  let purchaseLineCount=0;
  function addPurchaseLine(){const container=$('#purchase-lines');if(!container)return;const id=++purchaseLineCount;const line=document.createElement('div');line.className='form-grid purchase-line';line.dataset.line=id;line.style.cssText='padding:13px 0;border-bottom:1px solid var(--line);margin-top:9px';line.innerHTML=`<div class="field full"><label for="po-product-${id}">Produto *</label><select id="po-product-${id}" name="product_id" required>${productOptions('')}</select></div><div class="field"><label for="po-qty-${id}">Quantidade *</label><input id="po-qty-${id}" name="quantity" type="number" min="0.001" step="0.001" value="1" required></div><div class="field"><label for="po-cost-${id}">Custo unitário (R$) *</label><input id="po-cost-${id}" name="unit_cost" type="number" min="0" step="0.01" value="0" required></div><div class="field full"><button class="btn btn-danger btn-sm" type="button" data-action="remove-purchase-line" data-id="${id}">Remover item</button></div>`;container.append(line);}
  function showSaleDetails(s){modalOpen(`Venda ${s.code}`,`<div class="modal-note">${dateTime(s.created_at)} · ${esc(paymentLabel(s.payment_method))} · ${s.status==='completed'?'Concluída':'Cancelada'}</div><div class="table-wrap"><table class="data-table" style="min-width:400px"><thead><tr><th>Produto</th><th>Qtd.</th><th>Preço un.</th><th>Desconto</th><th>Total</th></tr></thead><tbody>${s.items.map(i=>`<tr><td><strong>${esc(i.product_name)}</strong><div class="helper">${esc(i.sku)}</div></td><td>${qty(i.quantity)}</td><td>${brl(i.unit_price)}</td><td>${brl(i.line_discount)}</td><td><strong>${brl(i.line_total)}</strong></td></tr>`).join('')}</tbody></table></div><div class="cart-total"><div><span>Subtotal</span><br><span>Descontos: ${brl(s.discount)}</span></div><strong>${brl(s.total)}</strong></div><div class="form-actions"><button class="btn btn-primary" data-close-modal>Fechar</button></div>`);}
  function showPurchaseDetails(p){modalOpen(`Pedido ${p.code}`,`<div class="modal-note">${esc(p.supplier_name||'Sem fornecedor')} · ${dateShort(p.created_at)} · ${p.status==='draft'?'Rascunho':p.status==='received'?'Recebido':'Cancelado'}</div><div class="table-wrap"><table class="data-table" style="min-width:370px"><thead><tr><th>Produto</th><th>Quantidade</th><th>Custo unit.</th><th>Total</th></tr></thead><tbody>${p.items.map(i=>`<tr><td>${esc(i.product_name)}<div class="helper">${esc(i.sku)}</div></td><td>${qty(i.quantity)} ${esc(i.unit)}</td><td>${brl(i.unit_cost)}</td><td><strong>${brl(i.line_total)}</strong></td></tr>`).join('')}</tbody></table></div><div class="cart-total"><span>Total estimado</span><strong>${brl(p.total)}</strong></div>${p.status==='draft'&&state.user.role!=='cashier'?`<div class="form-actions"><button class="btn btn-outline" data-close-modal>Fechar</button><button class="btn btn-primary" data-action="receive-purchase" data-id="${p.id}">Receber compra</button></div>`:`<div class="form-actions"><button class="btn btn-primary" data-close-modal>Fechar</button></div>`}`);}
  async function viewAudit(){try{const rows=await api('/api/audit');modalOpen('Registro de auditoria',`<div class="table-wrap"><table class="data-table" style="min-width:450px"><thead><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Entidade</th><th>Detalhe</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td>${dateTime(r.created_at)}</td><td>${esc(r.username||'Sistema')}</td><td>${esc(r.action)}</td><td>${esc(r.entity)} #${r.entity_id||'—'}</td><td>${esc(r.details)}</td></tr>`).join(''):`<tr><td colspan="5">Sem eventos por enquanto.</td></tr>`}</tbody></table></div><div class="form-actions"><button class="btn btn-primary" data-close-modal>Fechar</button></div>`);}catch(e){}}
  function targetOptions(type,selected=''){const items=type==='product'?state.products:state.categories;return `<option value="">Selecione ${type==='product'?'um produto':'uma categoria'}</option>${items.map(x=>`<option value="${x.id}" ${String(selected)===String(x.id)?'selected':''}>${esc(x.name)}</option>`).join('')}`;}

  document.addEventListener('click',async e=>{
    const nav=e.target.closest('[data-nav]');if(nav){if(nav.hasAttribute('data-close-modal'))modalClose();await navigate(nav.dataset.nav);return;}
    const close=e.target.closest('[data-close-modal]');if(close){modalClose();return;}
    const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=Number(b.dataset.id);
    try{
      switch(action){
        case'toggle-nav':$('#sidebar')?.classList.toggle('open');break;
        case'logout':await api('/api/logout',{method:'POST',body:{}}).catch(()=>{});state.user=null;state.csrf='';state.cart=[];renderAuth(false);break;
        case'quick-search':await navigate('products');setTimeout(()=>$('#product-search')?.focus(),30);break;
        case'new-product':productForm();break;
        case'edit-product':{const p=state.products.find(x=>x.id===id);if(p)productForm(p);else{await api('/api/products').then(x=>state.products=x);productForm(state.products.find(x=>x.id===id));}break;}
        case'archive-product':if(confirm('Arquivar este produto? A ação não apaga as vendas antigas.')){await api(`/api/products/${id}`,{method:'DELETE',body:{}});await loadPage('products');renderApp();toast('Produto arquivado.');}break;
        case'new-category':categoryForm();break;
        case'edit-category':categoryForm(state.categories.find(x=>x.id===id));break;
        case'delete-category':if(confirm('Excluir esta categoria? Categorias usadas por produtos não podem ser excluídas.')){await api(`/api/categories/${id}`,{method:'DELETE',body:{}});await loadPage('categories');renderApp();toast('Categoria excluída.');}break;
        case'new-discount':discountForm();break;
        case'toggle-discount':await api(`/api/discounts/${id}`,{method:'PATCH',body:{active:b.dataset.active==='1'}});await loadPage('discounts');renderApp();toast('Status da promoção atualizado.');break;
        case'delete-discount':if(confirm('Excluir esta promoção?')){await api(`/api/discounts/${id}`,{method:'DELETE',body:{}});await loadPage('discounts');renderApp();toast('Promoção excluída.');}break;
        case'stock-move':stockForm();break;
        case'toggle-low':state.showLow=!state.showLow;await loadPage('stock');renderApp();break;
        case'cart-add':{const p=state.products.find(x=>x.id===id);if(!p){await api('/api/products').then(x=>state.products=x);}const prod=state.products.find(x=>x.id===id);if(!prod)return;const existing=state.cart.find(x=>x.id===id);if(existing){const step=['kg','g','L','ml','m'].includes(prod.unit)?0.1:1;const next=Math.round((existing.quantity+step)*1000)/1000;if(next>prod.stock){toast('Quantidade maior que o estoque disponível.','error');return;}existing.quantity=next;}else{if(prod.stock<=0){toast('Produto sem estoque suficiente.','error');return;}const initial=['kg','g','L','ml','m'].includes(prod.unit)?Math.min(1,prod.stock):1;if(initial>prod.stock){toast('Produto sem estoque suficiente.','error');return;}state.cart.push({id:prod.id,name:prod.name,quantity:initial,currentPrice:prod.sale_price,discount:prod.effective_discount_bp||0,unit:prod.unit,stock:prod.stock});}renderApp();break;}
        case'cart-qty':{const c=state.cart.find(x=>x.id===id);if(c){const p=state.products.find(x=>x.id===id);const step=['kg','g','L','ml','m'].includes(p.unit)?0.1:1;const val=Math.round((c.quantity+Number(b.dataset.delta)*step)*1000)/1000;if(val<=0)state.cart=state.cart.filter(x=>x.id!==id);else if(val>p.stock)toast('Quantidade maior que o estoque disponível.','error');else c.quantity=val;renderApp();}break;}
        case'cart-remove':state.cart=state.cart.filter(x=>x.id!==id);renderApp();break;
        case'clear-cart':if(confirm('Limpar todos os itens do carrinho?')){state.cart=[];renderApp();}break;
        case'new-expense':expenseForm();break;
        case'delete-expense':if(confirm('Excluir este lançamento de despesa?')){await api(`/api/expenses/${id}`,{method:'DELETE',body:{}});await loadPage('finance');renderApp();toast('Despesa removida.');}break;
        case'new-supplier':supplierForm();break;
        case'new-customer':customerForm();break;
        case'new-purchase':purchaseForm();break;
        case'add-purchase-line':addPurchaseLine();break;
        case'remove-purchase-line':$(`.purchase-line[data-line="${id}"]`)?.remove();break;
        case'receive-purchase':{const p=state.purchases.find(x=>x.id===id);const go=confirm(`Confirmar recebimento do pedido ${p?.code||''}? Isso adicionará as quantidades ao estoque e atualizará o custo unitário.`);if(go){await api(`/api/purchases/${id}/receive`,{method:'POST',body:{}});modalClose();await loadPage('purchases');renderApp();toast('Compra recebida e estoque atualizado.');}break;}
        case'purchase-details':{const p=state.purchases.find(x=>x.id===id);if(p)showPurchaseDetails(p);break;}
        case'sale-details':{const s=state.sales.find(x=>x.id===id);if(s)showSaleDetails(s);break;}
        case'cancel-sale':{const reason=prompt('Motivo do cancelamento (obrigatório):');if(!reason?.trim())break;if(confirm('Cancelar esta venda e devolver os itens ao estoque?')){await api(`/api/sales/${id}/cancel`,{method:'POST',body:{reason:reason.trim()}});await loadPage('sales');renderApp();toast('Venda cancelada e estoque revertido.');}break;}
        case'new-user':userForm();break;
        case'view-audit':viewAudit();break;
      }
    }catch(err){/* API layer already announces the failure. */}
  });

  document.addEventListener('input',e=>{
    if(e.target.id==='product-search'){
      state.query=e.target.value;
      const paint=()=>{const rows=state.products.filter(p=>[p.name,p.sku,p.barcode,p.category_name].join(' ').toLowerCase().includes(state.query.toLowerCase()));const tbody=$('.data-table tbody');if(tbody&&state.page==='products')tbody.innerHTML=productTable(rows);const badge=$('.toolbar .pill');if(badge&&state.page==='products')badge.textContent=`${rows.length} produto(s)`;};
      paint();clearTimeout(productSearchTimer);const seq=++productSearchSeq;const q=state.query.trim();
      productSearchTimer=setTimeout(async()=>{try{const found=await api('/api/products?q='+encodeURIComponent(q));if(seq!==productSearchSeq||state.page!=='products')return;const byId=new Map(state.products.map(p=>[p.id,p]));for(const p of found)byId.set(p.id,p);state.products=[...byId.values()];paint();}catch(err){}},180);
    }
    if(e.target.id==='stock-search'&&state.stock){const q=e.target.value.toLowerCase();const rows=state.stock.products.filter(p=>[p.name,p.sku,p.category_name].join(' ').toLowerCase().includes(q));const tbody=$('.data-table tbody');if(tbody&&state.page==='stock')tbody.innerHTML=rows.length?rows.map(p=>`<tr><td><div class="product-cell">${productThumb(p)}<div><strong>${esc(p.name)}</strong><small>${esc(p.sku)}</small></div></div></td><td>${esc(p.category_name||'Sem categoria')}</td><td><strong>${qty(p.stock)} ${esc(p.unit)}</strong></td><td>${qty(p.min_stock)} ${esc(p.unit)}</td><td>${stockPill(p.stock,p.min_stock)}</td><td>${brl(p.unit_cost)}</td></tr>`).join(''):`<tr><td colspan="6">Nenhum resultado.</td></tr>`;}
    if(e.target.id==='customer-search'){state.query=e.target.value;const tbody=$('.data-table tbody');if(tbody&&state.page==='customers')tbody.innerHTML=state.customers.filter(c=>[c.name,c.phone,c.document,c.email].join(' ').toLowerCase().includes(state.query.toLowerCase())).map(c=>`<tr><td><strong>${esc(c.name)}</strong><div class="helper">ID #${c.id}</div></td><td>${esc(c.phone||'—')}</td><td>${esc(c.email||'—')}</td><td>${esc(c.document||'—')}</td><td>${esc(c.notes||'—')}</td><td>${dateShort(c.created_at)}</td></tr>`).join('')||`<tr><td colspan="6">Nenhum cliente encontrado.</td></tr>`;}
    if(e.target.id==='pos-search'){
      const q=e.target.value.trim();const target=$('#pos-product-list');const local=state.products.filter(p=>p.stock>0&&[p.name,p.sku,p.barcode].join(' ').toLowerCase().includes(q.toLowerCase()));if(target)target.innerHTML=posProductItems(local.slice(0,q?50:20));
      clearTimeout(posSearchTimer);const seq=++posSearchSeq;posSearchTimer=setTimeout(async()=>{try{const found=await api('/api/products?q='+encodeURIComponent(q));if(seq!==posSearchSeq||state.page!=='pos')return;const byId=new Map(state.products.map(p=>[p.id,p]));for(const p of found)byId.set(p.id,p);state.products=[...byId.values()];const list=found.filter(p=>p.stock>0);const el=$('#pos-product-list');if(el)el.innerHTML=posProductItems(list.slice(0,q?50:20));}catch(err){}},180);
    }
  });
  document.addEventListener('change',e=>{
    if(e.target.id==='d-type'){const sel=$('#d-target');if(sel)sel.innerHTML=targetOptions(e.target.value);const lab=$('label[for="d-target"]');if(lab)lab.textContent=e.target.value==='product'?'Produto *':'Categoria *';}
    if(e.target.id==='st-kind'){const l=$('#st-qty-label');const q=$('#st-qty');if(l)l.textContent=e.target.value==='adjustment'?'Estoque físico contado *':'Quantidade a adicionar *';if(q)q.min=e.target.value==='adjustment'?'0':'0.001';}
    if(e.target.matches('[data-cart-quantity]')){const id=Number(e.target.dataset.cartQuantity);const c=state.cart.find(x=>x.id===id);const val=Number(e.target.value);if(!c)return;if(!Number.isFinite(val)||val<=0||val>c.stock){toast('Informe uma quantidade positiva que não ultrapasse o estoque.','error');e.target.value=String(c.quantity);return;}if(!['kg','g','L','ml','m'].includes(c.unit)&&!Number.isInteger(val)){toast('Para unidades, caixas e pacotes, use uma quantidade inteira.','error');e.target.value=String(c.quantity);return;}c.quantity=Math.round(val*1000)/1000;renderApp();}
  });
  document.addEventListener('submit',async e=>{
    const form=e.target;if(!(form instanceof HTMLFormElement))return;
    if(form.id==='period-filter'){
      e.preventDefault();const fd=new FormData(form);state.dateFrom=fd.get('from');state.dateTo=fd.get('to');if(state.dateFrom>state.dateTo){toast('A data inicial deve ser anterior à final.','error');return;}try{await loadPage(state.page);renderApp();}catch(err){}return;
    }
    if(form.id==='product-form'){
      e.preventDefault();const fd=new FormData(form);const id=form.dataset.id;const body=Object.fromEntries(fd.entries());body.category_id=body.category_id?Number(body.category_id):null;for(const k of ['cost','price','min_stock','stock'])if(body[k]!==undefined)body[k]=Number(body[k]);try{if(id)await api(`/api/products/${id}`,{method:'PUT',body});else await api('/api/products',{method:'POST',body});modalClose();await loadPage('products');renderApp();toast(id?'Produto atualizado.':'Produto cadastrado.');}catch(err){}return;
    }
    if(form.id==='category-form'){
      e.preventDefault();const fd=new FormData(form);const id=form.dataset.id;const body=Object.fromEntries(fd.entries());try{if(id)await api(`/api/categories/${id}`,{method:'PUT',body});else await api('/api/categories',{method:'POST',body});modalClose();await loadPage('categories');renderApp();toast(id?'Categoria atualizada.':'Categoria criada.');}catch(err){}return;
    }
    if(form.id==='discount-form'){
      e.preventDefault();const fd=new FormData(form);const body=Object.fromEntries(fd.entries());body.target_id=Number(body.target_id);body.percent=Number(body.percent);try{await api('/api/discounts',{method:'POST',body});modalClose();await loadPage('discounts');renderApp();toast('Promoção criada.');}catch(err){}return;
    }
    if(form.id==='stock-form'){
      e.preventDefault();const fd=new FormData(form);const body=Object.fromEntries(fd.entries());body.product_id=Number(body.product_id);body.quantity=Number(body.quantity);try{await api('/api/stock',{method:'POST',body});modalClose();await loadPage('stock');renderApp();toast('Estoque atualizado.');}catch(err){}return;
    }
    if(form.id==='expense-form'){
      e.preventDefault();const body=Object.fromEntries(new FormData(form).entries());body.amount=Number(body.amount);try{await api('/api/expenses',{method:'POST',body});modalClose();await loadPage('finance');renderApp();toast('Despesa registrada.');}catch(err){}return;
    }
    if(form.id==='supplier-form'){
      e.preventDefault();const body=Object.fromEntries(new FormData(form).entries());try{await api('/api/suppliers',{method:'POST',body});modalClose();await loadPage('purchases');renderApp();toast('Fornecedor cadastrado.');}catch(err){}return;
    }
    if(form.id==='customer-form'){
      e.preventDefault();const body=Object.fromEntries(new FormData(form).entries());try{await api('/api/customers',{method:'POST',body});modalClose();await loadPage(state.page);renderApp();toast('Cliente cadastrado.');}catch(err){}return;
    }
    if(form.id==='user-form'){
      e.preventDefault();const body=Object.fromEntries(new FormData(form).entries());try{await api('/api/users',{method:'POST',body});modalClose();await loadPage('settings');renderApp();toast('Usuário criado.');}catch(err){}return;
    }
    if(form.id==='purchase-form'){
      e.preventDefault();const fd=new FormData(form);const lines=$$('.purchase-line',form).map(line=>({product_id:Number($('[name="product_id"]',line).value),quantity:Number($('[name="quantity"]',line).value),unit_cost:Number($('[name="unit_cost"]',line).value)}));const body={supplier_id:fd.get('supplier_id')?Number(fd.get('supplier_id')):null,notes:fd.get('notes'),items:lines};if(!lines.length){toast('Adicione ao menos um item.','error');return;}try{await api('/api/purchases',{method:'POST',body});modalClose();await loadPage('purchases');renderApp();toast('Pedido de compra criado como rascunho.');}catch(err){}return;
    }
    if(form.id==='checkout-form'){
      e.preventDefault();if(!state.cart.length){toast('Adicione ao menos um produto.','error');return;}const fd=new FormData(form);const body={items:state.cart.map(c=>({product_id:c.id,quantity:c.quantity})),payment_method:fd.get('payment_method'),customer_id:fd.get('customer_id')?Number(fd.get('customer_id')):null,notes:fd.get('notes')};const btn=$('button[type="submit"]',form);btn.disabled=true;btn.textContent='Confirmando venda...';try{const result=await api('/api/sales/checkout',{method:'POST',body});state.cart=[];await loadPage('pos');renderApp();toast(`Venda ${result.code} concluída · ${brl(result.total)}`);modalOpen('Venda concluída',`<div class="empty-state"><div class="empty-illustration">✓</div><strong style="font-size:18px">${esc(result.code)}</strong><p>Venda registrada, estoque atualizado e movimentos salvos.</p><div class="finance-number" style="margin:15px 0">${brl(result.total)}</div><p>Subtotal ${brl(result.subtotal)} · Descontos ${brl(result.discount)}</p></div><div class="form-actions"><button class="btn btn-primary" data-close-modal>Continuar vendendo</button><button class="btn btn-outline" data-nav="sales" data-close-modal>Ver histórico</button></div>`,'VENDA REGISTRADA');}catch(err){btn.disabled=false;btn.textContent='✓ Finalizar venda';}return;
    }
  });
  modal.addEventListener('click',e=>{if(e.target===modal)modalClose();});
  modal.addEventListener('close',()=>{modalContent.innerHTML='';});
  // Native links and API exports use the same-origin session cookie; downloads do not modify state.
  window.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.open)modalClose();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&state.user){e.preventDefault();navigate('products').then(()=>$('#product-search')?.focus());}});
  boot();
})();
